hsgLesson(document.getElementById("gate-l12"),"quiz12");
const PR12=[{label:"Ví dụ: sort mặc định với pair",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<pair<int, int>> v;\n    v.push_back({5, 1});\n    v.push_back(make_pair(2, 9));\n    v.emplace_back(2, 4);\n    v.push_back({5, 0});\n    sort(v.begin(), v.end());\n    for (auto p : v) cout << \"(\" << p.first << \", \" << p.second << \") \";\n    cout << \"\\n\";\n    sort(v.begin(), v.end(), greater<pair<int, int>>());\n    for (auto p : v) cout << \"(\" << p.first << \", \" << p.second << \") \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v"}]},{label:"Ví dụ: Xếp hạng theo điểm rồi tên",input:"5\nLan 8\nAn 9\nBinh 8\nChi 10\nDung 9",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nbool cmp(const pair<int, string>& a, const pair<int, string>& b) {\n    if (a.first != b.first) return a.first > b.first;   // điểm cao đứng trước\n    return a.second < b.second;                         // cùng điểm: tên theo bảng chữ cái\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"XEPHANG.INP\", \"r\")) {\n        freopen(\"XEPHANG.INP\", \"r\", stdin);\n        freopen(\"XEPHANG.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    vector<pair<int, string>> v;\n    for (int i = 0; i < n; i++) {\n        string ten;\n        int diem;\n        cin >> ten >> diem;\n        v.push_back({diem, ten});\n    }\n    sort(v.begin(), v.end(), cmp);\n    for (auto p : v) cout << p.second << \" \" << p.first << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"v"}]},{label:"Ví dụ: Sắp xếp giữ chỉ số ban đầu",input:"",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    vector<int> a = {40, 10, 30, 10, 20};\n    int n = a.size();\n    vector<pair<int, int>> b;\n    for (int i = 0; i < n; i++) b.push_back({a[i], i + 1});   // (giá trị, số thứ tự)\n    sort(b.begin(), b.end());\n    for (int i = 0; i < n; i++) cout << b[i].second << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"cells",of:"b"}]}];
const sim12=makeSim2(document.getElementById("sim-l12"),{id:"s12",presets:PR12,tools:true});
makeEx2(document.getElementById("ex-l12"),sim12,[{t:"Xếp hạng",d:"File XEPHANG.INP: dòng 1 là n (1 ≤ n ≤ 1000), n dòng sau mỗi dòng có tên (một từ không dấu, ≤ 20 ký tự) và điểm (0..100). Ghi vào XEPHANG.OUT danh sách tên, mỗi tên một dòng, theo điểm giảm dần; cùng điểm thì theo tên tăng dần (thứ tự từ điển).",tests:[{in:"5\nLan 8\nAn 9\nBinh 8\nChi 10\nDung 9",out:"Chi\nAn\nDung\nBinh\nLan"},{in:"1\nX 0",out:"X"},{in:"3\nb 5\na 5\nc 5",out:"a\nb\nc"},{in:"4\nMinh 100\nHa 0\nKhoa 50\nAnh 50",out:"Minh\nAnh\nKhoa\nHa"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nbool cmp(const pair<int, string>& a, const pair<int, string>& b) {\n    // điểm giảm dần; cùng điểm thì tên tăng dần\n    return false;\n}\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"XEPHANG.INP\", \"r\")) {\n        freopen(\"XEPHANG.INP\", \"r\", stdin);\n        freopen(\"XEPHANG.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    vector<pair<int, string>> v;\n    // đọc, sắp xếp bằng hàm cmp, in tên\n    return 0;\n}",file:"XEPHANG"},{t:"Thứ tự ban đầu",d:"File THUTU.INP: dòng 1 là n (1 ≤ n ≤ 10^5), dòng 2 là n số nguyên (≤ 10^9). Ghi vào THUTU.OUT số thứ tự ban đầu (đánh số từ 1) của các phần tử khi xếp theo giá trị tăng dần; giá trị bằng nhau thì số thứ tự nhỏ hơn đứng trước.",tests:[{in:"5\n40 10 30 10 20",out:"2 4 5 3 1"},{in:"1\n7",out:"1"},{in:"3\n3 3 3",out:"1 2 3"},{in:"4\n-5 1000000000 0 -5",out:"1 4 3 2"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"THUTU.INP\", \"r\")) {\n        freopen(\"THUTU.INP\", \"r\", stdin);\n        freopen(\"THUTU.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    // ghép (giá trị, số thứ tự) rồi sắp xếp\n    return 0;\n}",file:"THUTU",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>(i*7919)%100003).join(" "),ns:[300,1200,4800],need:"nlogn",limit:n=>Math.round(60*n*Math.log2(n))+500,why:"Tìm phần tử nhỏ nhất còn lại rồi in, lặp n lần, là O(n²). Ghép (giá trị, số thứ tự) và dùng sort một lần: O(n log n)."}},{t:"Tổng độ dài các đoạn",d:"File DOAN.INP: dòng 1 là n (1 ≤ n ≤ 10^5), n dòng sau mỗi dòng hai số l < r (0 ≤ l < r ≤ 10^9) là một đoạn trên trục số. Ghi vào DOAN.OUT tổng độ dài phần trục số được phủ bởi ít nhất một đoạn.",tests:[{in:"3\n1 3\n2 5\n7 8",out:"5"},{in:"1\n0 1000000000",out:"1000000000"},{in:"2\n1 2\n2 3",out:"2"},{in:"3\n5 9\n1 10\n2 3",out:"9"},{in:"2\n0 1\n5 6",out:"2"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"DOAN.INP\", \"r\")) {\n        freopen(\"DOAN.INP\", \"r\", stdin);\n        freopen(\"DOAN.OUT\", \"w\", stdout);\n    }\n    int n;\n    cin >> n;\n    vector<pair<int, int>> d(n);\n    for (int i = 0; i < n; i++) cin >> d[i].first >> d[i].second;\n    // sắp các đoạn theo đầu trái, rồi gộp các đoạn chồng nhau\n    return 0;\n}",file:"DOAN",perf:{gen:n=>n+"\n"+Array.from({length:n},(_,i)=>{const l=(i*7919)%100000;return l+" "+(l+1+(i*31)%50)}).join("\n"),ns:[300,1200,4800],need:"nlogn",limit:n=>Math.round(60*n*Math.log2(n))+500,why:"Đánh dấu từng điểm trên trục số không dùng được khi tọa độ tới 10⁹. Sắp xếp đoạn rồi gộp một lượt: O(n log n)."}}]);

makeQuiz("quiz12","score12",[{"q": "Sau <code>sort<\/code> mặc định, vector các cặp {(2, 9), (1, 5), (2, 3)} có thứ tự:", "o": ["(1, 5) (2, 9) (2, 3)", "(1, 5) (2, 3) (2, 9)", "(2, 3) (2, 9) (1, 5)", "(2, 9) (2, 3) (1, 5)"], "a": 1, "e": "So first trước; first bằng nhau (2 và 2) thì so second."}, {"q": "Hàm so sánh nào sắp xếp điểm giảm dần một cách đúng?", "o": ["return a.first >= b.first;", "return a.first - b.first;", "return a.first < b.first;", "return a.first > b.first;"], "a": 3, "e": "cmp phải trả về false khi hai phần tử bằng nhau, nên dùng > chứ không dùng >=."}, {"q": "Truyền hàm so sánh cho sort viết thế nào?", "o": ["sort(v.begin(), v.end(), cmp());", "sort(v.begin(), v.end(), cmp);", "sort(cmp, v.begin(), v.end());", "sort(v.begin(), v.end()).cmp;"], "a": 1, "e": "Truyền tên hàm làm tham số thứ ba, không có ngoặc."}, {"q": "Để in số thứ tự ban đầu theo giá trị tăng dần, cách gọn nhất là:", "o": ["Sắp mảng giá trị rồi tìm lại từng giá trị", "Sắp mảng số thứ tự", "Không làm được bằng sort", "Sắp vector các cặp (giá trị, số thứ tự)"], "a": 3, "e": "Cặp mang theo số thứ tự, và khi giá trị bằng nhau thì số thứ tự nhỏ đứng trước."}, {"q": "<code>v.emplace_back(2, 4);<\/code> với <code>v<\/code> là <code>vector&lt;pair&lt;int, int&gt;&gt;<\/code> làm gì?", "o": ["Thêm hai phần tử 2 và 4", "Thêm cặp (2, 4) vào cuối v", "Lỗi biên dịch", "Thay phần tử thứ 2 bằng 4"], "a": 1, "e": "emplace_back dựng cặp từ hai giá trị ngay trong vector, tương đương push_back({2, 4})."}]);

